BOTS = "['Кагэ', 'Рэн', 'Мидори', 'Хаято', 'Сора', 'Юкина', 'Тэнкай', 'Акира', 'Харуто', 'Цубаки', 'Рюдзи', 'Мэй', 'Кайто', 'Аянэ', 'Сэцуна', 'Дзин', 'Нацуки', 'Хотару', 'Иори', 'Кёка', 'Райдэн', 'Сакура', 'Тору', 'Минато']"
BOTS2 = "['Альрик', 'Бран', 'Мирра', 'Гаррет', 'Сайрус', 'Элла', 'Торин', 'Ариан', 'Кейл', 'Лира', 'Роланд', 'Мейв', 'Каэл', 'Айла', 'Седрик', 'Дейн', 'Нора', 'Халвар', 'Ивон', 'Кора', 'Рейнар', 'Сильвия', 'Тир', 'Марек']"
def apply(text):
    text = text.replace(BOTS, BOTS2)
    for a, b in R: text = text.replace(a, b)
    W = r'(?<![А-Яа-яЁёA-Za-z])'; E = r'(?![А-Яа-яЁёA-Za-z])'
    text = re.sub(W + 'мон' + E, 'зол.', text)
    text = re.sub(W + 'ки' + E, 'маны', text)
    text = re.sub(W + 'Ки' + E, 'Мана', text)
    return text
